const body = $input.first().json.body || $input.first().json;
const clientes = Array.isArray(body.clientes) ? body.clientes : (Array.isArray(body) ? body : [body]);

return clientes.map((cliente, index) => ({
  json: {
    id: cliente.id || `CLI-${index + 1}`,
    nome: cliente.nome || 'Investidor',
    email: cliente.email || '',
    saldo: typeof cliente.saldo === 'number' ? cliente.saldo : parseFloat(String(cliente.saldo || 0).replace(/[^0-9.]/g, '')),
    saldo_formatado: cliente.saldo_formatado || `R$ ${Number(cliente.saldo || 0).toFixed(2)}`,
    perfil: (cliente.perfil || 'Conservador').trim()
  }
}));

// Match Engine com Catálogo de Produtos e Preparação de Contexto para o Jev
const catalogo = [
  { perfil: 'Conservador', produto: 'Poupança', minimo: 100, rentabilidade: '6.2%' },
  { perfil: 'Conservador', produto: 'CDB Liquidez Diária', minimo: 1000, rentabilidade: '12.5%' },
  { perfil: 'Conservador', produto: 'Tesouro Selic', minimo: 500, rentabilidade: '13.0%' },
  { perfil: 'Moderado', produto: 'CDB Prefixado', minimo: 1000, rentabilidade: '14.0%' },
  { perfil: 'Moderado', produto: 'Fundo Multimercado', minimo: 5000, rentabilidade: '16.0%' },
  { perfil: 'Moderado', produto: 'Tesouro IPCA+', minimo: 1000, rentabilidade: 'IPCA+6.0%' },
  { perfil: 'Arrojado', produto: 'Ações ETF', minimo: 500, rentabilidade: 'Variável' },
  { perfil: 'Arrojado', produto: 'Fundo de Ações', minimo: 10000, rentabilidade: 'Variável' },
  { perfil: 'Arrojado', produto: 'Criptomoedas', minimo: 100, rentabilidade: 'Variável' }
];

const items = $input.all();
return items.map(item => {
  const c = item.json;
  const produtosPerfil = catalogo.filter(p => p.perfil.toLowerCase() === c.perfil.toLowerCase());
  const acessiveis = produtosPerfil.filter(p => c.saldo >= p.minimo);
  const recomendacao = acessiveis.length > 0 ? acessiveis[0] : produtosPerfil[0];

  const stateContext = `Cliente: ${c.nome} (ID: ${c.id})\nSaldo Líquido: ${c.saldo_formatado}\nPerfil Declarado: ${c.perfil}\nProduto Recomendado: ${recomendacao.produto} (Mínimo: R$ ${recomendacao.minimo}, Rentabilidade: ${recomendacao.rentabilidade})`;

  return {
    json: {
      ...c,
      recomendacao,
      typesafe_payload: {
        model: 'jev-1.13',
        state: stateContext,
        questions: {
          suitability: {
            type: 'choice',
            question: 'O ativo recomendado está estritamente adequado ao perfil e saldo do investidor?',
            options: [
              { id: 'conforme', description: 'Ativo 100% adequado' },
              { id: 'inadequado', description: 'Ativo fora da conformidade de risco' }
            ]
          },
          despacho_automatico: {
            type: 'noul',
            question: 'Pode ser enviado diretamente para o cliente sem revisão humana?'
          }
        }
      }
    }
  };
});

const item = $input.first().json;
return [{
  json: {
    status: 'AUTO_APPROVED',
    confidence: item.confidence,
    acao: 'Recomendação despachada diretamente para o investidor.',
    resultado_jev: item
  }
}];

const item = $input.first().json;
return [{
  json: {
    status: 'HUMAN_REVIEW_REQUIRED',
    confidence: item.confidence,
    acao: 'Encaminhado para a fila de compliance do Assessor Santander.',
    resultado_jev: item
  }
}];
